-- 75th percentile of order price by customer country | mysql
-- Generated by scripts/export-demo-sql.ts; display formatting only.
-- Ordered sample parameters: [0.75,0,1]
-- r8 aggregate: merged; Compatible row-level input block
-- r5 project: merged; Compatible row-level input block
-- r2 project: merged; Compatible row-level input block
-- r1 aggregate: boundary; Preserve project input scope or specialized lowering boundary
-- r0 sort: merged; Track output ordering without a new query block
select
  `r12`.`c0` as `country`,
  cast(
    (
      max(
        case
          when `r12`.`rn` = floor(`r12`.`pos`)
          and `r12`.`n` > 0 then `r12`.`v`
        end
      ) + (
        max(
          case
            when `r12`.`rn` = ceil(`r12`.`pos`)
            and `r12`.`n` > 0 then `r12`.`v`
          end
        ) - max(
          case
            when `r12`.`rn` = floor(`r12`.`pos`)
            and `r12`.`n` > 0 then `r12`.`v`
          end
        )
      ) * max(`r12`.`pos` - floor(`r12`.`pos`))
    ) as decimal(38, 10)
  ) as `order_price_p75`
from
  (
    select
      `r1`.`c0` as `c0`,
      `r1`.`c1` as v,
      row_number() over (
        partition by
          `r1`.`c0`
        order by
          case
            when `r1`.`c1` is null then 1
            else 0
          end,
          `r1`.`c1`
      ) as rn,
      count(`r1`.`c1`) over (
        partition by
          `r1`.`c0`
      ) as n,
      (
        1 + cast(? as decimal(38, 10)) * (
          count(`r1`.`c1`) over (
            partition by
              `r1`.`c0`
          ) - 1
        )
      ) as pos
    from
      (
        select
          `r3`.`country` as `c0`,
          `r11`.`c1` as `c1`
        from
          `customers` as `r3`
          inner join (
            select
              `r6`.`customer_id` as `c0`,
              cast(
                coalesce(`r10`.`c1`, cast(? as signed)) as decimal(38, 10)
              ) as `c1`
            from
              `orders` as `r6`
              left join (
                select
                  `order_details`.`order_id` as `c0`,
                  cast(
                    sum(
                      cast(
                        (
                          cast(
                            (
                              cast(`order_details`.`unit_price` as decimal(38, 10)) * cast(`order_details`.`quantity` as decimal(38, 10))
                            ) as decimal(38, 10)
                          ) * cast(
                            (
                              cast(cast(? as signed) as decimal(38, 10)) - cast(`order_details`.`discount` as decimal(38, 10))
                            ) as decimal(38, 10)
                          )
                        ) as decimal(38, 10)
                      )
                    ) as decimal(38, 10)
                  ) as `c1`
                from
                  `order_details`
                group by
                  `order_details`.`order_id`
              ) as `r10` on (`r6`.`order_id` = `r10`.`c0`)
          ) as `r11` on (
            cast(`r3`.`customer_id` as binary) = cast(`r11`.`c0` as binary)
          )
      ) as `r1`
  ) as `r12`
group by
  `r12`.`c0`
order by
  case
    when `r12`.`c0` is null then 1
    else 0
  end asc,
  `r12`.`c0` asc;
